import {
  Link as RemixLink,
  useLocation,
  useNavigate,
  useParams,
} from "@remix-run/react";
import type { LinkProps } from "@remix-run/react";
import { useCallback, forwardRef } from "react";
import { defaultLng, normalizeLanguageCode } from "@/i18n/languages";

function getLocaleFromPathname(pathname: string) {
  const firstSegment = pathname.split("/").filter(Boolean)[0];
  return normalizeLanguageCode(firstSegment);
}

function getBrowserLocale() {
  if (typeof window === "undefined") return null;
  return getLocaleFromPathname(window.location.pathname);
}

function isExternalPath(path: string) {
  return /^[a-z][a-z\d+\-.]*:/i.test(path) || path.startsWith("//");
}

function localizePath(path: string, locale: string) {
  if (!path || isExternalPath(path) || path.startsWith("#")) return path;

  const hashIndex = path.indexOf("#");
  const pathBeforeHash = hashIndex >= 0 ? path.slice(0, hashIndex) : path;
  const hash = hashIndex >= 0 ? path.slice(hashIndex) : "";
  const searchIndex = pathBeforeHash.indexOf("?");
  const pathname =
    searchIndex >= 0 ? pathBeforeHash.slice(0, searchIndex) : pathBeforeHash;
  const search = searchIndex >= 0 ? pathBeforeHash.slice(searchIndex) : "";
  const cleanPathname = pathname.startsWith("/") ? pathname : `/${pathname}`;
  const firstSegment = cleanPathname.split("/").filter(Boolean)[0];

  if (normalizeLanguageCode(firstSegment)) {
    return `${cleanPathname}${search}${hash}`;
  }

  return `/${locale}${cleanPathname}${search}${hash}`;
}

function useCurrentLocale(locale?: string) {
  const { lang } = useParams<{ lang: string }>();
  const location = useLocation();
  return (
    normalizeLanguageCode(locale) ||
    getBrowserLocale() ||
    normalizeLanguageCode(lang) ||
    getLocaleFromPathname(location.pathname) ||
    defaultLng
  );
}

function localizeTo(to: LinkProps["to"], locale: string): LinkProps["to"] {
  if (typeof to === "string") return localizePath(to, locale);
  return {
    ...to,
    pathname: to.pathname ? localizePath(to.pathname, locale) : to.pathname,
  };
}

export function useLocalePath(path: string, locale?: string) {
  const effectiveLocale = useCurrentLocale(locale);
  return localizePath(path, effectiveLocale);
}

export function useLocalizedPath() {
  const locale = useCurrentLocale();

  return useCallback(
    (path: string) => {
      return localizePath(path, locale);
    },
    [locale]
  );
}

export const LocalizedLink = forwardRef<HTMLAnchorElement, LinkProps>(
  function LocalizedLink({ to, ...rest }, ref) {
    const locale = useCurrentLocale();
    const localePath = localizeTo(to, locale);
    return <RemixLink to={localePath} {...rest} ref={ref} />;
  }
);

export function useLocalizedNavigate() {
  const navigate = useNavigate();
  const locale = useCurrentLocale();

  return useCallback(
    (path: string, options?: { replace?: boolean }) => {
      navigate(localizePath(path, locale), options);
    },
    [navigate, locale]
  );
}

export function useLocalizedBack(fallbackPath: string) {
  const navigate = useNavigate();
  const locale = useCurrentLocale();

  return useCallback(() => {
    if (
      typeof window !== "undefined" &&
      Number(window.history.state?.idx || 0) > 0
    ) {
      navigate(-1);
      return;
    }

    navigate(localizePath(fallbackPath, locale));
  }, [fallbackPath, navigate, locale]);
}
